";foreach(string line in data.Split('\n')){string[] p=line.Trim().Split('|');if(p.Length==6)Entries[p[0]]=p;}}
  public static string Description(string type){string[] p;if(!Entries.TryGetValue(type,out p))return FxCatalog.Description(type);return Language.English?p[2]+"\r\nAPP: "+p[4]:p[1]+"\r\nAPP: "+p[3];}
  public static string Source(string type){string[] p;return Entries.TryGetValue(type,out p)?"https://www.jlc.style/"+p[5]:"https://www.jlc.style/glossary";}
